export const DICT = D;
/** Registra stringhe aggiuntive di un modulo (le chiavi del nucleo non si possono sovrascrivere). */
export function registerStrings(it, en) {
  for (const [lang, src] of [['it', it], ['en', en]]) for (const [k, v] of Object.entries(src || {})) { if (!(k in CORE[lang])) D[lang][k] = v; }
}
const CORE = { it: { ...D.it }, en: { ...D.en } };
export const CORE_KEYS = CORE;
let current = 'it';
export const getLang = () => current;
export function setLang(l) { current = D[l] ? l : 'it'; return current; }
export function detectLang() {
  try { const n = (navigator.language || 'it').slice(0, 2).toLowerCase(); return D[n] ? n : 'it'; } catch { return 'it'; }
}
/** Traduce una chiave. `params` sostituisce {segnaposto}. */
export function tr(lang, key, params) {
  let s = (D[lang] && D[lang][key]) ?? D.it[key] ?? key;
  if (params) s = s.replace(/\{(\w+)\}/g, (m, k) => (params[k] !== undefined && params[k] !== null ? String(params[k]) : m));
  return s;
}
export const t = (key, params) => tr(current, key, params);

// ---------- formattazione date ----------
const pd = (s) => { const [y, m, d] = s.split('-').map(Number); return { y, m: m - 1, d, dow: new Date(Date.UTC(y, m - 1, d)).getUTCDay() }; };
export function fmtDate(s, lang = current, o = {}) {
  if (!s) return '';
  const { y, m, d, dow } = pd(s);
  const mon = tr(lang, 'mon.' + m);
  let out = `${d} ${mon}`;
  if (o.year) out += ` ${y}`;
  if (o.dow) out = `${tr(lang, 'dow.' + dow)} ${out}`;
  return out;
}
/** Intervallo lun–dom di una settimana che termina alla domenica `sunday`. */
export function fmtWeekRange(sunday, lang = current) {
  const a = pd(addDaysStr(sunday, -6)), b = pd(sunday);
  const ma = tr(lang, 'mon.' + a.m), mb = tr(lang, 'mon.' + b.m);
  return a.m === b.m ? `${a.d}–${b.d} ${mb}` : `${a.d} ${ma} – ${b.d} ${mb}`;
}
export function addDaysStr(s, k) { const { y, m, d } = pd(s); return new Date(Date.UTC(y, m, d + k)).toISOString().slice(0, 10); }
export function dowLong(s, lang = current) { return tr(lang, 'dowl.' + pd(s).dow); }
